# English captions (seconds in the ORIGINAL recording NAF003.mp3). *word* = shown in gold.
# Cleaned from the TurboScribe translation for the Shorts. Lines in “quotes” are read from the book Nizam-ul-Amal-e-Fuqara.
# The full dars needs the rest of the transcript (from 18:06) before its captions are complete.
CAPTIONS = [
    # ---- Taqwa
    (55.48, 72.42, "The topic is *Taqwa*. “Remember: Taqwa begins with *repentance*.”"),
    (72.42, 87.51, "“Taqwa is to keep away from everything that *harms* you.”"),
    (98.61, 121.15, "“Taqwa is to eat *less*, sleep *less*, speak *less*, to weep over one's own wrongs, and to overlook the faults of others.”"),
    (124.56, 128.91, "What else is there but *humility*? Allahu Akbar."),
    (128.91, 150.99, "Now we must look within: are these things in us, or are we guilty of the opposite? Then we must try to *get rid* of them."),
    # ---- The Sufi is the son of time
    (180.13, 189.29, "“A *Sufi* is the son of *time*.” The past is gone."),
    (189.29, 204.09, "The future is unknown. Now, what do you have in your hands? Only your *present* state, this moment."),
    (205.11, 212.19, "When the time comes, the work comes with it. If you put today's work off to tomorrow, when will you do tomorrow's work?"),
    (213.97, 236.03, "Tell me: after becoming a murid, what troubles does Shaytan put us in? This should not happen. That is why I keep saying: read this book. It teaches not only the murid, but the *shaykh* too."),
    (239.05, 243.19, "So whatever you have to do, do it *today*."),
    # ---- Tawakkul
    (320.48, 329.64, "“A person has many needs and many aims. To think that your own efforts alone will fulfil them is wrong.”"),
    (332.08, 361.64, "“To fulfil your needs, you must *trust* in Allah”: to turn to Him, to ask Him for help, to hope that Allah will give me. This connection with Allah is a very special thing."),
    (364.07, 374.39, "“To rely on Allah for your needs: this is called *Tawakkul*.”"),
    (404.21, 427.30, "“*Not working* is not tawakkul.” “I'm sitting here; Allah will do whatever He wants.” How can that be? You must work. Do something!"),
    (427.97, 438.25, "“That is *seeking comfort*: wasting your hands and feet, the powers Allah has given you.”"),
    (438.95, 456.71, "That is great *disrespect* to Allah. Whatever Allah has given you, use it. If you don't, you are disrespecting Allah."),
    (457.53, 467.07, "MashaAllah. It is a small topic, but see how it changes a whole *life*."),
    # ---- Istikhara
    (608.45, 618.40, "“Whatever work you have to do, do it by *asking* Allah.” This is *Istikhara*."),
    (618.55, 633.29, "“O Allah, I want to do such-and-such work, I want to write such-and-such a book. Grant me the ability to do it.”"),
    (635.09, 646.65, "After this you feel *peace* within. “Yes, now I am at peace”: it means you have been given leave for this work. This is Istikhara."),
    (648.29, 662.11, "For a daughter's marriage too: “Will this relationship be right for our child?” Ask *Allah*. This is Istikhara."),
    (665.13, 676.41, "Very few people know this. I don't even tell it, or else they will reach great heights and I'll be left behind!"),
    (680.95, 711.47, "Before, I told you how to make murids. Now I am telling you how to do Istikhara. Pay attention: “O Allah, let me know whether I should do it or not.” Whatever you do, *ask Allah* first."),
    # ---- Two rakats better than a hundred
    (850.41, 864.15, "A person stayed up the *whole night* in prayer, and went to sleep just before morning."),
    (865.11, 893.49, "And he *missed* the Fajr prayer. He couldn't pray it. The fard prayer is Allah's command; he had to keep it, and he missed it."),
    (897.07, 915.35, "Another person also stayed up the night, and in the morning he prayed the two rakats of *fard*. Do you see?"),
    (917.73, 931.00, "Clearly, his *two rakats* are better than a hundred rakats of the night vigil, because they are under the *command*."),
    (931.24, 938.52, "Command. Order. Whose? Allah's. Allah's command is to pray the fard before sunrise."),
    (940.72, 958.32, "He prayed the sunnah and the fard. If there isn't time for the sunnah, leave the sunnah and pray the *fard*."),
    (961.22, 1001.92, "It is by Allah's command: it belongs to *Qurb-e-Faraiz*, nearness through the obligatory. A hundred rakats of one's own choosing, *Qurb-e-Nawafil*, cannot compare with these two rakats."),
]
